import sympy as sp
from sympy.logic.boolalg import And, Or, Not, Xor, BooleanTrue, BooleanFalse, simplify_logic

# Decode each ReLU as an exact positive weighted threshold over the prior
# Boolean signals. Minimal weighted covers give a symbolic DNF; no network
# activations or input assignments are evaluated.
def threshold_expr(coeffs, bias, xs):
    pos, neg = [], []
    for c, x in zip(coeffs, xs):
        c = int(round(float(c)))
        if c > 0:
            pos.append((c, x))
        elif c < 0:
            neg.append((-c, Not(x)))
    base = int(round(float(bias))) - sum(w for w, _ in neg)
    terms = pos + neg
    need = 1 - base
    if need <= 0:
        return BooleanTrue()
    if not terms or sum(w for w, _ in terms) < need:
        return BooleanFalse()

    # Enumerate minimal covers of positive integer weights, not input tuples.
    covers = []
    for r in range(1, len(terms) + 1):
        for ids in itertools.combinations(range(len(terms)), r):
            if sum(terms[i][0] for i in ids) < need:
                continue
            if any(set(prev).issubset(ids) for prev in covers):
                continue
            covers.append(ids)
    cubes = [And(*(terms[i][1] for i in ids)) for ids in covers]
    return simplify_logic(Or(*cubes), force=True)

